def G(t):
    R=[("Google AI Professional Certificate","Гугл Ей-Ай Профешнл Сертифікейт"),("AI Essentials","Ей-Ай Ессеншлз"),("Google AI Pro","Гугл Ей-Ай Про"),
       ("Gemini Live","Джеміні Лайв"),("Gemini Notebook","Джеміні Ноутбук"),("Deep Research","Діп Ресьорч"),("Gemini","Джеміні"),
       ("Google Meet","Гугл Міт"),("Google Slides","Гугл Слайдз"),("Google Sheets","Гугл Шітс"),("AI Studio","Ей-Ай Студіо"),("grow.google","гроу крапка гугл"),
       ("Google","Гугл"),("Coursera","Курсера"),("LinkedIn","Лінкедін"),("Djinni","Джинні"),("DOU","Доу"),("dev.ua","дев юа"),
       ("ChatGPT","Чат Джі-Пі-Ті"),("Claude","Клод"),("YouTube","Ютуб"),("IT","ай-ті")]
    for a,b in R: t=re.sub(r"(?<![\w-])"+re.escape(a)+r"(?![\w])", b, t)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("на ШІ","на штучний інтелект"),("у ШІ","у штучний інтелект")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

